	@Test
	void ordinaryAddsUseAlignedBatchesWithoutDiskReplay(@TempDir Path dataDir) throws Exception {
		LmdbStoreConfig config = smallMaps();
		AtomicReference<ObservingTripleStore> observed = new AtomicReference<>();
		Set<Statement> expected = statements(STATEMENT_COUNT);

		try (LmdbSailStore store = newStore(dataDir, config, observed)) {
			assertEquals(0, countPersistentSetEnvironments(dataDir),
					"NONE-only store startup must not create temporary PersistentSet environments");
			try (SailSink sink = store.getExplicitSailSource(WRITER_OWNER).sink(IsolationLevels.NONE)) {
				for (Statement statement : expected) {
					sink.approve(statement.getSubject(), statement.getPredicate(), statement.getObject(),
							statement.getContext());
				}
				sink.flush();
			}

			ObservingTripleStore triples = observed.get();
			assertNotNull(triples, "the instrumented TripleStore factory must be used");
			assertTrue(triples.alignedBatchCount.get() > 0,
					"ordinary NONE additions must reach the aligned TripleStore writer");
			assertEquals(STATEMENT_COUNT, triples.alignedStatementCount.get(),
					"every configured-size batch should use aligned writes");
			assertEquals(0, triples.scalarWriteCount.get(),
					"ordinary NONE additions should not fall back to scalar triple writes");
			assertFalse(triples.diskReplayJournalObserved.get(),
					"NONE ingestion should not create a disk-backed transaction replay journal");
			assertEquals(expected, readStatements(store), "flushed contents must match the submitted statements");
		}

		try (LmdbSailStore reopened = newStore(dataDir, config, new AtomicReference<>())) {
			assertEquals(expected, readStatements(reopened), "committed contents must survive close and reopen");
		}
	}

	@Test
	void mixedUpdateRowsDoNotCheckpointEachAddRemovePair(@TempDir Path dataDir) throws Exception {
		int rowCount = 32;
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc")
				.setBulkOperationSize(BULK_OPERATION_SIZE)
				.setTripleDBSize(16L << 20)
				.setValueDBSize(16L << 20)
				.setMapGrowthThreshold(0.99d);
		IRI predicate = VALUE_FACTORY.createIRI("http://www.w3.org/1999/02/22-rdf-syntax-ns#type");
		IRI previousType = VALUE_FACTORY.createIRI("urn:none-streaming:mixed-update:previous");
		IRI replacementType = VALUE_FACTORY.createIRI("urn:none-streaming:mixed-update:replacement");
		List<Statement> originalRows = new ArrayList<>(rowCount);
		Set<Statement> original = new HashSet<>(rowCount);
		Set<Statement> expected = new HashSet<>(rowCount);
		for (int index = 0; index < rowCount; index++) {
			Resource subject = VALUE_FACTORY.createIRI("urn:none-streaming:mixed-update:subject:" + index);
			Statement oldStatement = VALUE_FACTORY.createStatement(subject, predicate, previousType);
			originalRows.add(oldStatement);
			original.add(oldStatement);
			expected.add(VALUE_FACTORY.createStatement(subject, predicate, replacementType));
		}

		ObservingLmdbStore sail = new ObservingLmdbStore(dataDir.toFile(), config);
		try {
			sail.init();
			try (LmdbStoreConnection seed = (LmdbStoreConnection) sail.getConnection()) {
				seed.begin(IsolationLevels.READ_COMMITTED);
				for (Statement statement : originalRows) {
					add(seed, statement);
				}
				seed.commit();
			}

			long checkpointsBeforeUpdate = sail.getBackingStore().noneIngestionMetrics().checkpoints();
			try (LmdbStoreConnection writer = (LmdbStoreConnection) sail.getConnection()) {
				writer.begin(IsolationLevels.NONE);
				UpdateContext update = new UpdateContext(new InsertData("INSERT DATA {}"), null, null, false);
				writer.startUpdate(update);
				for (Statement oldStatement : originalRows) {
					Statement newStatement = expected.stream()
							.filter(statement -> statement.getSubject().equals(oldStatement.getSubject()))
							.findFirst()
							.orElseThrow();
					writer.addStatement(update, newStatement.getSubject(), newStatement.getPredicate(),
							newStatement.getObject(), new Resource[0]);
					writer.removeStatement(update, oldStatement.getSubject(), oldStatement.getPredicate(),
							oldStatement.getObject(), new Resource[0]);
				}
				assertEquals(checkpointsBeforeUpdate, sail.getBackingStore().noneIngestionMetrics().checkpoints(),
						"mixed UpdateContext mutations must batch add/remove pairs until the update boundary");
				writer.endUpdate(update);
				writer.commit();
			}
			assertEquals(expected, readStatements(sail.getBackingStore()),
					"the mixed update must replace every old type with its corresponding new type");
		} finally {
			sail.shutDown();
		}

		ObservingLmdbStore reopened = new ObservingLmdbStore(dataDir.toFile(), config);
		try {
			reopened.init();
			assertEquals(expected, readStatements(reopened.getBackingStore()),
					"the completed mixed update must survive store reopen");
		} finally {
			reopened.shutDown();
		}
	}

	@Test
	void queuedAlignedMapFullRecoversBeforeMixedRemovalCapture(@TempDir Path dataDir) throws Exception {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc")
				.setBulkOperationSize(2)
				.setTripleDBSize(16L << 20)
				.setValueDBSize(16L << 20)
				.setMapGrowthThreshold(0.99d);
		ObservingLmdbStore sail = new ObservingLmdbStore(dataDir.toFile(), config);
		Statement removed = statement("queued-map-full", 1);
		Statement companion = statement("queued-map-full", 3);
		CopyOnWriteArrayList<Statement> listenerAdditions = new CopyOnWriteArrayList<>();
		CopyOnWriteArrayList<Statement> listenerRemovals = new CopyOnWriteArrayList<>();
		try {
			sail.init();
			LmdbSailStore backing = sail.getBackingStore();
			backing.enableMultiThreading = true;
			ObservingTripleStore triples = sail.triples.get();
			assertNotNull(triples, "the instrumented TripleStore factory must be used");
			long growthEpisodesBefore = backing.growthMetricsSnapshot().growthEpisodes();
			long checkpointsBefore = backing.noneIngestionMetrics().checkpoints();
			try (LmdbStoreConnection writer = (LmdbStoreConnection) sail.getConnection()) {
				writer.addConnectionListener(new SailConnectionListener() {
					@Override
					public void statementAdded(Statement statement) {
						listenerAdditions.add(statement);
					}

					@Override
					public void statementRemoved(Statement statement) {
						listenerRemovals.add(statement);
					}
				});
				writer.begin(IsolationLevels.NONE);
				UpdateContext update = new UpdateContext(new InsertData("INSERT DATA {}"), null, null, false);
				writer.startUpdate(update);
				triples.failNextAlignedBatchWithMapFullAfterMutation();
				writer.addStatement(update, removed.getSubject(), removed.getPredicate(), removed.getObject(),
						new Resource[0]);
				writer.addStatement(update, companion.getSubject(), companion.getPredicate(), companion.getObject(),
						new Resource[0]);
				assertEquals(checkpointsBefore, backing.noneIngestionMetrics().checkpoints(),
						"the queued two-row batch must not checkpoint before the removal barrier");
				assertTrue(triples.awaitAlignedMapFullFailure(10, TimeUnit.SECONDS),
						"the asynchronous aligned write must encounter injected MAP_FULL after mutating its native transaction");
				assertNotSame(Thread.currentThread(), triples.alignedMapFullFailureThread(),
						"the failing aligned batch must execute on the native writer worker");
				assertDoesNotThrow(() -> writer.removeStatement(update, removed.getSubject(), removed.getPredicate(),
						removed.getObject(), new Resource[0]),
						"the next bounded mutation read must recover the queued native MAP_FULL and remove its row");
				assertEquals(List.of(removed), List.copyOf(listenerRemovals),
						"the removal barrier must enumerate the newly-added row after recovery");
				assertTrue(writer.isActive(), "capacity recovery must preserve the public NONE transaction");
				assertEquals(1, triples.alignedMapFullFailureCount.get(),
						"the fault must be injected exactly once after the aligned native mutation");
				assertEquals(List.of(removed, companion), List.copyOf(listenerAdditions),
						"replaying the owned chunk must not repeat caller-facing addition notifications");
				assertTrue(backing.growthMetricsSnapshot().growthEpisodes() > growthEpisodesBefore,
						"the removal barrier must complete managed growth while recovering the queued MAP_FULL");
				assertTrue(backing.noneIngestionMetrics().capacityReplays() > 0,
						"the removal barrier must complete bounded NONE capacity replay before update end");
				writer.endUpdate(update);
				writer.commit();
			}
			assertEquals(Set.of(companion), readStatements(backing),
					"the remove must be applied once while the companion row remains");
		} finally {
			sail.shutDown();
		}

		LmdbStore reopened = new LmdbStore(dataDir.toFile(), config);
		try {
			reopened.init();
			assertEquals(Set.of(companion), readStatements(reopened.getBackingStore()),
					"the recovered mixed chunk and exact removal must survive reopening");
		} finally {
			reopened.shutDown();
		}
	}

