	@Test
	void queuedRemovalMapFullRecoversAtNextNoListenerPageCapture(@TempDir Path dataDir) throws Exception {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc")
				.setBulkOperationSize(2)
				.setTripleDBSize(16L << 20)
				.setValueDBSize(16L << 20)
				.setMapGrowthThreshold(0.99d);
		ObservingLmdbStore sail = new ObservingLmdbStore(dataDir.toFile(), config);
		IRI predicate = VALUE_FACTORY.createIRI("urn:none-streaming:queued-remove:predicate");
		Value object = VALUE_FACTORY.createLiteral("victim");
		List<Statement> victims = new ArrayList<>();
		for (int index = 0; index < 4; index++) {
			Resource subject = VALUE_FACTORY.createIRI("urn:none-streaming:queued-remove:subject:" + index);
			victims.add(VALUE_FACTORY.createStatement(subject, predicate, object));
		}
		Statement keeper = VALUE_FACTORY.createStatement(
				VALUE_FACTORY.createIRI("urn:none-streaming:queued-remove:keeper"), predicate,
				VALUE_FACTORY.createLiteral("keeper"));
		IRI additionPredicate = VALUE_FACTORY.createIRI("urn:none-streaming:queued-remove:addition-predicate");
		List<Statement> additions = List.of(
				VALUE_FACTORY.createStatement(VALUE_FACTORY.createIRI("urn:none-streaming:queued-remove:addition:0"),
						additionPredicate, VALUE_FACTORY.createLiteral("addition-0")),
				VALUE_FACTORY.createStatement(VALUE_FACTORY.createIRI("urn:none-streaming:queued-remove:addition:1"),
						additionPredicate, VALUE_FACTORY.createLiteral("addition-1")));
		Set<Statement> expected = new HashSet<>(additions);
		expected.add(keeper);
		try {
			sail.init();
			LmdbSailStore backing = sail.getBackingStore();
			backing.enableMultiThreading = true;
			ObservingTripleStore triples = sail.triples.get();
			assertNotNull(triples, "the instrumented TripleStore factory must be used");
			try (LmdbStoreConnection seed = (LmdbStoreConnection) sail.getConnection()) {
				seed.begin(IsolationLevels.READ_COMMITTED);
				for (Statement victim : victims) {
					add(seed, victim);
				}
				add(seed, keeper);
				seed.commit();
			}
			Set<Statement> seeded = new HashSet<>(victims);
			seeded.add(keeper);
			assertEquals(seeded, readStatements(backing),
					"the committed victim page and keeper must be present before deletion");
			long growthEpisodesBefore = backing.growthMetricsSnapshot().growthEpisodes();
			try (LmdbStoreConnection writer = (LmdbStoreConnection) sail.getConnection()) {
				writer.begin(IsolationLevels.NONE);
				UpdateContext update = new UpdateContext(new InsertData("DELETE WHERE {}"), null, null, false);
				writer.startUpdate(update);
				for (Statement addition : additions) {
					writer.addStatement(update, addition.getSubject(), addition.getPredicate(), addition.getObject(),
							new Resource[0]);
				}
				triples.failNextRemovalBatchWithMapFullAfterMutation();
				assertDoesNotThrow(() -> writer.removeStatement(update, null, predicate, object, new Resource[0]),
						"the next no-listener native page capture must recover a queued removal MAP_FULL");
				assertTrue(triples.awaitNativeRemovalMapFullFailure(10, TimeUnit.SECONDS),
						"the asynchronous native removal must encounter injected MAP_FULL after mutating its transaction");
				assertNotSame(Thread.currentThread(), triples.nativeRemovalMapFullFailureThread(),
						"the failing removal page must execute on the native writer worker");
				assertEquals(1, triples.nativeRemovalMapFullFailureCount.get(),
						"the queued removal failure must be injected exactly once");
				assertTrue(writer.isActive(), "capacity recovery must preserve the public NONE transaction");
				assertTrue(backing.growthMetricsSnapshot().growthEpisodes() > growthEpisodesBefore,
						"the next page capture must complete managed growth while recovering the queued removal");
				assertTrue(backing.noneIngestionMetrics().capacityReplays() > 0,
						"the next page capture must replay the bounded delete prefix before update end");
				writer.endUpdate(update);
				writer.commit();
			}
			assertEquals(expected, readStatements(backing),
					"the recovered paged delete must remove every matching victim and retain unrelated writes");
		} finally {
			sail.shutDown();
		}

		LmdbStore reopened = new LmdbStore(dataDir.toFile(), config);
		try {
			reopened.init();
			assertEquals(expected, readStatements(reopened.getBackingStore()),
					"the recovered paged delete result and unrelated writes must survive reopening");
		} finally {
			reopened.shutDown();
		}
	}

	@Test
	void pendingNoneMutationRejectsAnExpiredDeadlineAndPreservesEarlierRows(@TempDir Path dataDir) throws Exception {
		ObservingLmdbStore sail = new ObservingLmdbStore(dataDir.toFile(), smallMaps());
		Statement accepted = statement("expired-pending", 1);
		Statement rejected = statement("expired-pending", 2);
		try {
			sail.init();
			ObservingTripleStore triples = sail.triples.get();
			assertNotNull(triples, "the instrumented TripleStore factory must be used");
			long generationBefore = triples.getNativeCommitGeneration();
			try (LmdbStoreConnection writer = (LmdbStoreConnection) sail.getConnection()) {
				writer.begin(IsolationLevels.NONE);
				try (SailSink sink = writer.getExplicitSailSource().sink(IsolationLevels.NONE)) {
					sink.approve(accepted.getSubject(), accepted.getPredicate(), accepted.getObject(),
							accepted.getContext());
					assertEquals(generationBefore, triples.getNativeCommitGeneration(),
							"the first small row must remain buffered before the deadline test");
					try (QueryExecutionDeadline deadline = QueryExecutionDeadline.start(1L);
							QueryExecutionDeadline.Scope ignored = deadline.enter()) {
						long deadlineBound = System.nanoTime() + TimeUnit.SECONDS.toNanos(5);
						while (!deadline.isExpired() && System.nanoTime() < deadlineBound) {
							Thread.yield();
						}
						assertTrue(deadline.isExpired(), "the deadline must expire before the second buffered row");
						assertThrows(QueryInterruptedException.class,
								() -> sink.approve(rejected.getSubject(), rejected.getPredicate(), rejected.getObject(),
										rejected.getContext()),
								"a pending NONE batch must honor the caller's expired deadline immediately");
					}
					sink.flush();
				}
				writer.commit();
			}
			assertEquals(Set.of(accepted), readStatements(sail.getBackingStore()),
					"deadline rejection must preserve the admitted prefix and omit the rejected row");
		} finally {
			sail.shutDown();
		}
	}

	@Test
	void pendingNoneMutationRejectsAnInterruptedCallerAndPreservesEarlierRows(@TempDir Path dataDir) throws Exception {
		ObservingLmdbStore sail = new ObservingLmdbStore(dataDir.toFile(), smallMaps());
		Statement accepted = statement("interrupted-pending", 1);
		Statement rejected = statement("interrupted-pending", 2);
		try {
			sail.init();
			ObservingTripleStore triples = sail.triples.get();
			assertNotNull(triples, "the instrumented TripleStore factory must be used");
			long generationBefore = triples.getNativeCommitGeneration();
			try (LmdbStoreConnection writer = (LmdbStoreConnection) sail.getConnection()) {
				writer.begin(IsolationLevels.NONE);
				try (SailSink sink = writer.getExplicitSailSource().sink(IsolationLevels.NONE)) {
					sink.approve(accepted.getSubject(), accepted.getPredicate(), accepted.getObject(),
							accepted.getContext());
					assertEquals(generationBefore, triples.getNativeCommitGeneration(),
							"the first small row must remain buffered before interrupting the caller");
					Thread.currentThread().interrupt();
					try {
						assertThrows(InterruptedSailException.class,
								() -> sink.approve(rejected.getSubject(), rejected.getPredicate(), rejected.getObject(),
										rejected.getContext()),
								"a pending NONE batch must reject a newly interrupted caller");
						assertTrue(Thread.currentThread().isInterrupted(),
								"rejecting the mutation must preserve the caller's interrupt status");
					} finally {
						Thread.interrupted();
					}
					sink.flush();
				}
				writer.commit();
			}
			assertEquals(Set.of(accepted), readStatements(sail.getBackingStore()),
					"interruption rejection must preserve the admitted prefix and omit the rejected row");
		} finally {
			Thread.interrupted();
			sail.shutDown();
		}
	}

