	@Test
	void iterableNoneRowsCaptureMutableLiteralBetweenElements(@TempDir Path dataDir) throws Exception {
		LmdbStoreConfig config = smallMaps();
		ObservingLmdbStore sail = new ObservingLmdbStore(dataDir.toFile(), config);
		SailRepository repository = new SailRepository(sail);
		repository.init();
		IRI predicate = VALUE_FACTORY.createIRI("urn:none-streaming:iterable-mutable:predicate");
		IRI firstSubject = VALUE_FACTORY.createIRI("urn:none-streaming:iterable-mutable:first-subject");
		IRI secondSubject = VALUE_FACTORY.createIRI("urn:none-streaming:iterable-mutable:second-subject");
		Statement expectedFirst = VALUE_FACTORY.createStatement(firstSubject, predicate,
				VALUE_FACTORY.createLiteral("first"));
		Statement expectedSecond = VALUE_FACTORY.createStatement(secondSubject, predicate,
				VALUE_FACTORY.createLiteral("second"));
		try {
			ObservingValueStore values = sail.values.get();
			assertNotNull(values, "the instrumented ValueStore factory must be used");
			LmdbLiteral mutable = values.createLiteral("first");
			Iterable<Statement> input = () -> new java.util.Iterator<>() {
				private int index;

				@Override
				public boolean hasNext() {
					return index < 2;
				}

				@Override
				public Statement next() {
					if (index == 0) {
						index++;
						return VALUE_FACTORY.createStatement(firstSubject, predicate, mutable);
					}
					if (index == 1) {
						index++;
						mutable.setLabel("second");
						return VALUE_FACTORY.createStatement(secondSubject, predicate, mutable);
					}
					throw new java.util.NoSuchElementException();
				}
			};
			try (RepositoryConnection writer = repository.getConnection()) {
				writer.begin(IsolationLevels.NONE);
				writer.add(input);
				writer.commit();
			}
			assertEquals(Set.of(expectedFirst, expectedSecond), readStatements(sail.getBackingStore()),
					"iterable admission must snapshot a mutable term before requesting the next input row");
		} finally {
			repository.shutDown();
		}

		LmdbStore reopened = new LmdbStore(dataDir.toFile(), config);
		try {
			reopened.init();
			assertEquals(Set.of(expectedFirst, expectedSecond), readStatements(reopened.getBackingStore()),
					"per-element iterable snapshots must survive close and reopen");
		} finally {
			reopened.shutDown();
		}
	}

